    const install=$('installApp'),dialog=$('installDialog'),installedKey='projetotrid-installed';let deferred=null;const standalone=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone;function markInstalled(){install.hidden=true;deferred=null;try{localStorage.setItem(installedKey,'yes')}catch{}}try{if(standalone||localStorage.getItem(installedKey)==='yes')install.hidden=true}catch{if(standalone)install.hidden=true}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e});window.addEventListener('appinstalled',markInstalled);install.addEventListener('click',async()=>{if(deferred){deferred.prompt();const choice=await deferred.userChoice;if(choice?.outcome==='accepted')markInstalled();deferred=null}else if(dialog.showModal){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),h=dialog.querySelector('h2'),p=dialog.querySelector('p');if(ios){h.textContent='Instale no iPhone ou iPad';p.textContent='No Safari, toque em Compartilhar e escolha “Adicionar à Tela de Início” para abrir o app em tela cheia.'}else{h.textContent='Instale no Android';p.textContent='Adicione a Projeto Trid à tela inicial para abrir em tela cheia. No Chrome, use o menu ⋮ e escolha “Instalar app” ou “Adicionar à tela inicial”.'}dialog.showModal()}});$('closeInstallDialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{}));
