    /* ===== validade, rascunho, padrões, pré-visualização, orçamentos salvos ===== */
    function validityInfo(){const el=$('validityDays');if(!el)return null;const n=parseInt(String(el.value||'').replace(/\D/g,''),10);if(!Number.isFinite(n)||n<1||n>365)return null;return{days:n,until:new Date(Date.now()+n*864e5).toLocaleDateString('pt-BR')}}
    if($('validityDays'))$('validityDays').addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,3);saveDraft()});

    /* rascunho automático (neste aparelho, por conta) */
    const DRAFT_KEY='projetotrid-draft-v1';let draftTimer=null;
    const draftKey=()=>authUser?`${DRAFT_KEY}:${authUser.id}`:null;
    function draftMeaningful(){return quotes.length>0||Object.keys(defaults).some(k=>String(data[k]??'')!==String(defaults[k]??''))}
    function writeDraft(){const key=draftKey();if(!key)return;const pending=!$('draftBanner').hidden;try{if(!draftMeaningful()){if(!pending)localStorage.removeItem(key);return}$('draftBanner').hidden=true;localStorage.setItem(key,JSON.stringify({data,quotes,index:Math.min(index,4),editMode,editQuoteIndex,discountMode,discountValue,shareMode,validity:$('validityDays')?.value||'',activeSavedQuoteId,ts:Date.now()}))}catch{}}
    function saveDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(writeDraft,500)}
    function flushDraft(){if(!draftTimer)return;clearTimeout(draftTimer);draftTimer=null;writeDraft()}
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushDraft()});window.addEventListener('pagehide',flushDraft);
    function readDraft(){const key=draftKey();if(!key)return null;try{const d=JSON.parse(localStorage.getItem(key)||'null');return d&&(d.data||d.quotes)?d:null}catch{return null}}
    function clearDraft(){clearTimeout(draftTimer);draftTimer=null;const key=draftKey();try{if(key)localStorage.removeItem(key)}catch{}}
    function restoreDraft(d){data={...defaults,...(d.data||{})};quotes=Array.isArray(d.quotes)?d.quotes:[];discountMode=['fixed','final'].includes(d.discountMode)?d.discountMode:'percent';discountValue=Number(d.discountValue)||0;activeSavedQuoteId=d.activeSavedQuoteId||null;editQuoteIndex=Number.isInteger(d.editQuoteIndex)?d.editQuoteIndex:null;editMode=!!d.editMode;document.querySelector(`input[name="discountMode"][value="${discountMode}"]`).checked=true;if($('validityDays'))$('validityDays').value=d.validity||'';if(quotes.length&&editQuoteIndex===null){renderResult();scrollResultToTop()}else{index=Math.min(4,Math.max(0,Number(d.index)||0));$('result').classList.remove('show');$('formCard').hidden=false;showStage()}}
    $('draftResume').addEventListener('click',()=>{const d=readDraft();$('draftBanner').hidden=true;if(d)restoreDraft(d)});
    $('draftDiscard').addEventListener('click',()=>{clearDraft();$('draftBanner').hidden=true});
    document.addEventListener('change',saveDraft);

    /* padrões salvos (valores que raramente mudam) */
    const originalDefaults={...defaults};
    const GROUPS={material:['filamentType','packPrice','packQty','waste'],impressao:['printerModel','energyRate','power','printerCost','lifeHours','maintenance'],trabalho:['setupMin','finishMin','laborRate','packaging'],preco:['failure','margin','salesFee','taxRate']};
