    function loadSavedDefaults(){const key=defaultsKey();if(!key)return;try{const d=JSON.parse(localStorage.getItem(key)||'null');if(d&&typeof d==='object')for(const k of Object.values(GROUPS).flat())if(k in d)defaults[k]=d[k]}catch{}}
    function afterLogin(){const pristine=!draftMeaningful();loadSavedDefaults();if(pristine&&!quotes.length){data={...defaults};if(!$('formCard').hidden)paintFields()}const d=readDraft(),box=$('draftBanner');if(d&&pristine&&!quotes.length&&Date.now()-d.ts<2592e6&&(d.quotes?.length||Object.keys(defaults).some(k=>String(d.data?.[k]??'')!==String(defaults[k]??'')))){const when=new Date(d.ts),extra=d.quotes?.length?` · ${d.quotes.length} ${d.quotes.length===1?'item':'itens'} no pedido`:d.data?.product?` · ${d.data.product}`:'';$('draftInfo').textContent=`Salvo em ${when.toLocaleDateString('pt-BR')} às ${when.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}${extra}`;box.hidden=false}else box.hidden=true}
    document.querySelectorAll('.save-default,.reset-default').forEach(btn=>btn.addEventListener('click',()=>{const group=GROUPS[btn.dataset.group],key=defaultsKey(),note=btn.closest('.field-tools').querySelector('.tool-note');if(!group||!key)return;const saving=btn.classList.contains('save-default');try{if(saving&&group.some(k=>data[k]===''||data[k]==null)){note.textContent='Preencha todos os campos desta etapa antes de salvar.'}else{const saved=JSON.parse(localStorage.getItem(key)||'{}')||{};if(saving){group.forEach(k=>{saved[k]=data[k];defaults[k]=data[k]});note.textContent='Padrão salvo neste aparelho. Vale para os próximos orçamentos.'}else{group.forEach(k=>{delete saved[k];defaults[k]=originalDefaults[k]});note.textContent='Valores iniciais restaurados para os próximos orçamentos.'}localStorage.setItem(key,JSON.stringify(saved))}}catch{note.textContent='Não foi possível salvar neste navegador.'}setTimeout(()=>{note.textContent=''},5000)}));

    /* pré-visualização */
    const pdlg=$('previewDialog');let previewUrl=null,previewKind='image',previewToken=0;
    function setPreviewTab(kind){previewKind=kind;pdlg.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===kind)));$('previewAction').querySelector('.lbl').textContent=kind==='image'?'WhatsApp':'Baixar PDF'}
    async function showPreview(kind){const mine=++previewToken;setPreviewTab(kind);const body=$('previewBody'),msg=document.createElement('p');msg.className='preview-msg';msg.textContent='Preparando pré-visualização…';body.replaceChildren(msg);if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null}try{if(kind==='image'){const blob=await quoteBlob();if(mine!==previewToken)return;previewUrl=URL.createObjectURL(blob);const img=new Image();img.src=previewUrl;img.alt='Pré-visualização da imagem do orçamento';img.className='preview-img';body.replaceChildren(img)}else{await buildPDF();if(mine!==previewToken)return;const pages=window.__projetotridPdfPreview||[];body.replaceChildren(...pages.map((src,i)=>{const img=new Image();img.src=src;img.alt=`Página ${i+1} de ${pages.length} do PDF`;img.className='preview-img';return img}))}}catch{if(mine===previewToken)msg.textContent='Não foi possível gerar a pré-visualização. Tente novamente.'}}
