    let savedRecords=[],pendingDelete=null;const pendingDeleted=new Set();
    const norm=t=>String(t||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
    function renderSavedList(){const list=$('savedQuoteList'),status=$('savedQuotesStatus'),raw=$('savedSearch').value.trim(),q=norm(raw),sort=$('savedSort').value||'recent';const alive=savedRecords.filter(r=>!pendingDeleted.has(r.id));const rows=alive.filter(r=>!q||norm([r.title,r.client_name,r.client_email,r.client_phone].join(' ')).includes(q));const by={recent:(a,b)=>new Date(b.created_at)-new Date(a.created_at),oldest:(a,b)=>new Date(a.created_at)-new Date(b.created_at),value:(a,b)=>(Number(b.total)||0)-(Number(a.total)||0),client:(a,b)=>norm(a.client_name).localeCompare(norm(b.client_name),'pt-BR')};rows.sort(by[sort]||by.recent);if(window.ProjetoTridPedidos)rows.splice(0,rows.length,...window.ProjetoTridPedidos.filtrar(rows));list.replaceChildren();if(!rows.length){const empty=document.createElement('div'),icon=document.createElement('div'),symbol=document.createElementNS('http://www.w3.org/2000/svg','svg'),path=document.createElementNS('http://www.w3.org/2000/svg','path'),heading=document.createElement('h3'),copy=document.createElement('p');empty.className='saved-empty';icon.className='saved-empty-icon';icon.setAttribute('aria-hidden','true');symbol.setAttribute('viewBox','0 0 24 24');symbol.setAttribute('fill','none');symbol.setAttribute('stroke','currentColor');symbol.setAttribute('stroke-width','1.8');symbol.setAttribute('stroke-linecap','round');symbol.setAttribute('stroke-linejoin','round');path.setAttribute('d','M6 4h12v16l-6-4-6 4V4Z');symbol.append(path);icon.append(symbol);heading.textContent=alive.length?'Nenhum resultado encontrado':'Nenhum orçamento salvo ainda';copy.textContent=alive.length?'Tente outro termo ou limpe a busca para ver seus orçamentos.':'Salve um orçamento para acessá-lo depois nesta lista.';empty.append(icon,heading,copy);if(alive.length){const clear=document.createElement('button');clear.type='button';clear.className='btn btn-outline';clear.textContent='Limpar busca';clear.addEventListener('click',()=>{$('savedSearch').value='';renderSavedList();$('savedSearch').focus()});empty.append(clear)}else{const create=document.createElement('a');create.className='btn btn-primary';create.href='#top';create.textContent='Criar orçamento';empty.append(create)}list.append(empty)}rows.forEach(record=>{const row=document.createElement('article'),info=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small'),actions=document.createElement('div'),open=document.createElement('button'),remove=document.createElement('button');row.className='saved-quote-row';title.textContent=record.title||'Orçamento';const date=new Date(record.created_at).toLocaleDateString('pt-BR');meta.textContent=`${record.client_name||'Sem nome de cliente'} · ${date} · ${money.format(Number(record.total)||0)}`;info.append(title,meta);actions.className='saved-quote-actions';open.type='button';open.className='btn btn-sm btn-solid';open.textContent='Abrir';open.addEventListener('click',()=>loadSavedQuote(record));remove.type='button';remove.className='btn btn-sm btn-danger delete';remove.textContent='Excluir';remove.addEventListener('click',()=>deleteSavedQuote(record));actions.append(open,remove);window.ProjetoTridPedidos?.decorar(row,record,info,actions);row.append(info,actions);list.append(row)});const total=alive.length;status.textContent=!total?'Nenhum orçamento salvo ainda.':!rows.length?`Nenhum orçamento encontrado para “${raw}”.`:q?`${rows.length} de ${total} orçamentos.`:`${total} orçamento${total===1?'':'s'} salvo${total===1?'':'s'}.`}
