    $('undoBtn').addEventListener('click',()=>{if(!pendingDelete)return;clearTimeout(pendingDelete.timer);pendingDeleted.delete(pendingDelete.record.id);pendingDelete=null;$('undoToast').hidden=true;renderSavedList();$('savedQuotesStatus').textContent='Exclusão desfeita.'});
    
